import inspect
from dataclasses import dataclass
@dataclass
class Request:
    key:str
@dataclass
class Skip:
    reason:str

def evaluate_tick(callback,enabled=True):
    value=callback(enabled)
    values=list(value) if inspect.isgenerator(value) else [value]
    if any(not isinstance(v,(Request,Skip)) for v in values):raise TypeError('invalid_callback_item')
    requests=[v.key for v in values if isinstance(v,Request)]
    skips=[v.reason for v in values if isinstance(v,Skip)]
    return {'requests':requests,'skip':skips[0] if skips else None}

